     1→import { execSync, spawnSync, execFileSync } from 'child_process';
     2→import * as fs from 'fs';
     3→import * as path from 'path';
     4→import * as os from 'os';
     5→
     6→/**
     7→ * FVBridge: PyFree CLI에서 FV 2.0 Go 컴파일러를 호출하는 브릿지
     8→ *
     9→ * FV 소스 파일 (.fv)을 다음과 같이 처리:
    10→ * - compile: .fv → C 코드 (stdout)
    11→ * - build: .fv → 바이너리 (C → gcc)
    12→ * - run: .fv → 즉시 실행 (build + exec)
    13→ */
    14→export class FVBridge {
    15→  private fv2Binary: string;
    16→
    17→  constructor(binaryPath?: string) {
    18→    this.fv2Binary = binaryPath || this.findFV2Binary();
    19→  }
    20→
    21→  /**
    22→   * FV2 바이너리 자동 탐색
    23→   * 순서:
    24→   * 1. FV2_PATH 환경변수
    25→   * 2. PATH에서 fv2 찾기
    26→   * 3. 기본 경로: ~/projects/fv2-lang-go/bin/fv2
    27→   */
    28→  private findFV2Binary(): string {
    29→    // 1. 환경 변수 확인
    30→    if (process.env.FV2_PATH) {
    31→      const envPath = process.env.FV2_PATH;
    32→      if (fs.existsSync(envPath)) {
    33→        return envPath;
    34→      }
    35→      console.warn(`⚠️  FV2_PATH="${envPath}" does not exist`);
    36→    }
    37→
    38→    // 2. PATH에서 찾기
    39→    try {
    40→      const pathResult = execSync('which fv2', { encoding: 'utf-8' }).trim();
    41→      if (pathResult) {
    42→        return pathResult;
    43→      }
    44→    } catch {
    45→      // fv2가 PATH에 없음
    46→    }
    47→
    48→    // 3. 기본 경로
    49→    const homeDir = os.homedir();
    50→    const defaultPath = path.join(homeDir, 'projects', 'fv2-lang-go', 'bin', 'fv2');
    51→    if (fs.existsSync(defaultPath)) {
    52→      return defaultPath;
    53→    }
    54→
    55→    throw new Error(
    56→      `❌ FV2 compiler binary not found.\n\n` +
    57→      `Please set FV2_PATH or ensure "fv2" is in PATH.\n` +
    58→      `Expected default location: ${defaultPath}`
    59→    );
    60→  }
    61→
    62→  /**
    63→   * FV 소스 파일 → C 코드 생성
    64→   *
    65→   * @param fvFile FV 소스 파일 경로
    66→   * @returns 생성된 C 코드 (문자열)
    67→   */
    68→  compile(fvFile: string): string {
    69→    if (!fs.existsSync(fvFile)) {
    70→      throw new Error(`❌ File not found: ${fvFile}`);
    71→    }
    72→
    73→    try {
    74→      const cCode = execSync(`${this.fv2Binary} ${fvFile}`, {
    75→        encoding: 'utf-8',
    76→        stdio: ['pipe', 'pipe', 'pipe'], // 에러도 捕捉
    77→      });
    78→      return cCode;
    79→    } catch (error: any) {
    80→      throw new Error(
    81→        `❌ FV compilation failed:\n${error.stderr || error.message}`
    82→      );
    83→    }
    84→  }
    85→
    86→  /**
    87→   * FV 소스 파일 → 바이너리 빌드
    88→   *
    89→   * 단계:
    90→   * 1. compile() → C 코드
    91→   * 2. 임시 .c 파일에 저장
    92→   * 3. gcc로 바이너리 컴파일
    93→   * 4. 임시 .c 파일 삭제
    94→   *
    95→   * @param fvFile FV 소스 파일 경로
    96→   * @param outFile 출력 바이너리 경로
    97→   */
    98→  build(fvFile: string, outFile?: string): void {
    99→    // gcc 존재 여부 확인
   100→    if (!this.checkGCC()) {
   101→      throw new Error(
   102→        `❌ gcc/clang not found. Required for building .fv files.\n` +
   103→        `   Install with: apt-get install build-essential (Debian/Ubuntu) or\n` +
   104→        `                 brew install gcc (macOS) or\n` +
   105→        `                 pkg install clang (Termux)`
   106→      );
   107→    }
   108→
   109→    const output = outFile || 'a.out';
   110→
   111→    try {
   112→      // Step 1: C 코드 생성
   113→      console.log(`🔧 Compiling ${path.basename(fvFile)} to C...`);
   114→      const cCode = this.compile(fvFile);
   115→
   116→      // Step 2: 임시 C 파일 생성
   117→      const timestamp = Date.now();
   118→      const cFile = path.join(os.tmpdir(), `fv_build_${timestamp}.c`);
   119→      fs.writeFileSync(cFile, cCode);
   120→
   121→      // Step 3: gcc로 빌드
   122→      console.log(`🏗️  Building binary: ${output}`);
   123→      try {
   124→        execSync(`gcc -o ${output} ${cFile}`, { stdio: 'inherit' });
   125→      } catch (error) {
   126→        fs.unlinkSync(cFile); // 임시 파일 정리
   127→        throw error;
   128→      }
   129→
   130→      // Step 4: 임시 C 파일 정리
   131→      fs.unlinkSync(cFile);
   132→
   133→      console.log(`✅ Build successful: ${output}`);
   134→    } catch (error: any) {
   135→      throw new Error(`❌ Build failed: ${error.message}`);
   136→    }
   137→  }
   138→
   139→  /**
   140→   * FV 소스 파일 → 즉시 실행
   141→   *
   142→   * 단계:
   143→   * 1. build() → 임시 바이너리
   144→   * 2. spawnSync()로 실행
   145→   * 3. 임시 바이너리 정리
   146→   *
   147→   * @param fvFile FV 소스 파일 경로
   148→   */
   149→  run(fvFile: string): void {
   150→    const timestamp = Date.now();
   151→    const tempBinary = path.join(os.tmpdir(), `fv_run_${timestamp}`);
   152→
   153→    try {
   154→      // Step 1: 임시 바이너리로 빌드
   155→      this.build(fvFile, tempBinary);
   156→
   157→      // Step 2: 실행
   158→      console.log(`\n📍 Running ${path.basename(fvFile)}...\n`);
   159→      spawnSync(tempBinary, [], { stdio: 'inherit' });
   160→
   161→      // Step 3: 정리
   162→      if (fs.existsSync(tempBinary)) {
   163→        fs.unlinkSync(tempBinary);
   164→      }
   165→    } catch (error) {
   166→      // 임시 파일 정리
   167→      if (fs.existsSync(tempBinary)) {
   168→        try {
   169→          fs.unlinkSync(tempBinary);
   170→        } catch {
   171→          // 무시
   172→        }
   173→      }
   174→      throw error;
   175→    }
   176→  }
   177→
   178→  /**
   179→   * gcc/clang 존재 여부 확인
   180→   */
   181→  private checkGCC(): boolean {
   182→    try {
   183→      execSync('gcc --version', { stdio: 'pipe' });
   184→      return true;
   185→    } catch {
   186→      try {
   187→        execSync('clang --version', { stdio: 'pipe' });
   188→        return true;
   189→      } catch {
   190→        return false;
   191→      }
   192→    }
   193→  }
   194→}
