    23→/**
    24→ * PyFree 패키지 관리자
    25→ */
    26→class PyFreePkg {
    27→  private projectRoot: string;
    28→  private config?: PackageConfig;
    29→  private cache: PackageCache;
    30→  private fvBridge?: FVBridge;
    31→
    32→  constructor() {
    33→    this.projectRoot = process.cwd();
    34→    this.cache = new PackageCache();
    35→    try {
    36→      this.fvBridge = new FVBridge();
    37→    } catch {
    38→      // FV2 바이너리 없음 - PyFree만 사용하는 경우 허용
    39→      this.fvBridge = undefined;
    40→    }
    41→  }
    42→
    43→  /**
    44→   * 메인 진입점
    45→   */
    46→  async run(args: string[]): Promise<void> {
    47→    const command = args[0];
    48→
    49→    try {
    50→      switch (command) {
    51→        case 'init':
    52→          await this.handleInit(args.slice(1));
    53→          break;
    54→
    55→        case 'install':
    56→        case 'i':
    57→          await this.handleInstall(args.slice(1));
    58→          break;
    59→
    60→        case 'compile':
    61→          await this.handleCompile(args.slice(1));
    62→          break;
    63→
    64→        case 'build':
    65→          await this.handleBuild(args.slice(1));
    66→          break;
    67→
    68→        case 'test':
    69→          await this.handleTest(args.slice(1));
    70→          break;
    71→
    72→        case 'run':
    73→          await this.handleRun(args.slice(1));
    74→          break;
    75→
    76→        case 'publish':
    77→          await this.handlePublish(args.slice(1));
    78→          break;
    79→
    80→        case 'cache':
    81→          await this.handleCache(args.slice(1));
    82→          break;
    83→
    84→        case '--version':
    85→        case '-v':
    86→          this.printVersion();
    87→          break;
    88→
    89→        case '--help':
    90→        case '-h':
    91→        default:
    92→          this.printHelp();
    93→          break;
    94→      }
    95→    } catch (error) {
    96→      console.error('❌ 오류:', error instanceof Error ? error.message : error);
    97→      process.exit(1);
    98→    }
    99→  }
