   101→  /**
   102→   * init 명령어 - 새 프로젝트 초기화
   103→   */
   104→  private async handleInit(args: string[]): Promise<void> {
   105→    const projectName = args[0] || 'pyfree-project';
   106→    const projectPath = path.join(this.projectRoot, projectName);
   107→
   108→    if (fs.existsSync(projectPath)) {
