   174→  /**
   175→   * install 명령어 - 패키지 설치
   176→   */
   177→  private async handleInstall(args: string[]): Promise<void> {
   178→    if (args.length === 0) {
   179→      // pyfree.json 기반 설치
   180→      this.loadConfig();
   181→
   182→      if (!this.config) {
   183→        throw new Error('pyfree.json을 찾을 수 없습니다');
   184→      }
   185→
   186→      const deps = { ...this.config.dependencies };
   187→
   188→      for (const [name, version] of Object.entries(deps)) {
   189→        console.log(`📦 설치중: ${name}@${version}`);
   190→
   191→        // 실제 설치 로직
   192→        // - 레지스트리에서 메타데이터 조회
   193→        // - 캐시 확인
   194→        // - 없으면 다운로드
   195→        // - 캐시에 저장
   196→
   197→        const metadata = await defaultRegistry.getPackageInfo(name);
   198→
   199→        if (!metadata) {
   200→          console.warn(`⚠️  패키지를 찾을 수 없음: ${name}`);
   201→          continue;
   202→        }
   203→
   204→        const latestVersion = metadata.latestVersion;
   205→
   206→        if (!this.cache.hasPackage(name, latestVersion)) {
   207→          console.log(`  다운로드중...`);
   208→          const buffer = await defaultRegistry.downloadPackage(
   209→            name,
   210→            latestVersion
   211→          );
   212→
   213→          if (buffer) {
   214→            this.cache.cachePackage(name, latestVersion, '.');  // 실제로는 추출된 경로
   215→          }
   216→        }
   217→
   218→        console.log(`  ✓ ${name}@${latestVersion}`);
   219→      }
   220→
   221→      console.log('✅ 설치 완료');
   222→    } else {
   223→      // 특정 패키지 설치
   224→      const packageSpec = args[0];
   225→      const [name, version] = packageSpec.includes('@')
   226→        ? packageSpec.split('@')
   227→        : [packageSpec, 'latest'];
   228→
   229→      console.log(`📦 설치중: ${name}@${version}`);
   230→
   231→      const metadata = await defaultRegistry.getPackageInfo(name);
   232→
   233→      if (!metadata) {
