   342→      } else if (file.endsWith('.pf')) {
   343→        throw new Error('PyFree 파일은 빌드를 지원하지 않습니다. run 명령어를 사용하세요.');
   344→      } else {
   345→        throw new Error('지원하는 파일 형식: .fv (FV) 또는 .pf (PyFree)');
   346→      }
   347→    }
   348→  }
