   350→  /**
   351→   * test 명령어
   352→   */
   353→  private async handleTest(args: string[]): Promise<void> {
   354→    this.loadConfig();
   355→
   356→    if (!this.config) {
   357→      throw new Error('pyfree.json을 찾을 수 없습니다');
