     1→// FV 2.0 Compiler - V 언어로 재작성
     2→// 목표: 완전한 Lexer → Parser → Type Checker → Code Generator 파이프라인
     3→// 호환성: Go Compiler와 100% 동일
     4→
     5→// ============= 컴파일 결과 =============
     6→
     7→enum CompileStatus {
     8→	Success
     9→	LexerError
    10→	ParserError
    11→	TypeCheckError
    12→	CodeGenError
    13→}
    14→
    15→struct CompileResult {
    16→	status: CompileStatus
    17→	c_code: string
    18→	errors: []string
    19→	warnings: []string
    20→}
    21→
    22→// ============= 컴파일러 메인 구조체 =============
    23→
    24→struct Compiler {
    25→	mut source_code: string
    26→	mut tokens: []Token
    27→	mut ast: ?Program
    28→	mut type_checker: ?TypeChecker
    29→	mut code_generator: ?CodeGenerator
    30→	mut result: CompileResult
    31→	mut debug: bool
    32→}
    33→
    34→// ============= 컴파일러 초기화 =============
    35→
    36→fn new_compiler(source_code: string) Compiler {
    37→	return Compiler{
    38→		source_code: source_code,
    39→		tokens: [],
    40→		ast: none,
    41→		type_checker: none,
    42→		code_generator: none,
    43→		result: CompileResult{
    44→			status: CompileStatus.Success,
    45→			c_code: "",
    46→			errors: [],
    47→			warnings: []
    48→		},
    49→		debug: false
    50→	}
    51→}
    52→
    53→// ============= 디버그 모드 =============
    54→
    55→fn (mut c: Compiler) enable_debug() {
    56→	c.debug = true
    57→}
    58→
    59→fn (mut c: Compiler) log_debug(message: string) {
    60→	if c.debug {
    61→		println("[DEBUG] ${message}")
    62→	}
    63→}
    64→
    65→// ============= Phase 1: Lexer =============
    66→
    67→fn (mut c: Compiler) run_lexer() bool {
    68→	c.log_debug("Starting Lexer phase...")
    69→
    70→	mut lexer = new_lexer(c.source_code)
    71→	c.tokens = lexer.tokenize()
    72→
    73→	if lexer.has_errors() {
    74→		c.result.status = CompileStatus.LexerError
    75→		c.result.errors = lexer.get_errors()
    76→		c.log_debug("Lexer errors: ${c.result.errors.len()}")
    77→		return false
    78→	}
    79→
    80→	c.log_debug("Lexer completed: ${c.tokens.len()} tokens")
    81→	return true
    82→}
    83→
    84→// ============= Phase 2: Parser =============
    85→
    86→fn (mut c: Compiler) run_parser() bool {
    87→	c.log_debug("Starting Parser phase...")
    88→
    89→	mut parser = new_parser(c.tokens)
    90→	if let Some(program) = parser.parse() {
    91→		c.ast = program
    92→		c.log_debug("Parser completed successfully")
    93→		return true
    94→	}
    95→
    96→	c.result.status = CompileStatus.ParserError
    97→	c.result.errors = parser.errors
    98→	c.log_debug("Parser errors: ${c.result.errors.len()}")
    99→	return false
   100→}
   101→
   102→// ============= Phase 3: Type Checker =============
   103→
   104→fn (mut c: Compiler) run_type_checker() bool {
   105→	c.log_debug("Starting Type Checker phase...")
   106→
   107→	if c.ast == none {
   108→		c.result.errors.push("AST not available")
   109→		return false
   110→	}
   111→
   112→	mut tc = new_type_checker()
   113→	tc.register_builtin_types()
   114→
   115→	if tc.check() {
   116→		c.type_checker = tc
   117→		c.log_debug("Type Checker completed successfully")
   118→		return true
   119→	}
   120→
   121→	c.result.status = CompileStatus.TypeCheckError
   122→	c.result.errors = tc.get_errors().map(|e| e.message)
   123→	c.log_debug("Type Check errors: ${c.result.errors.len()}")
   124→	return false
   125→}
   126→
   127→// ============= Phase 4: Code Generator =============
   128→
   129→fn (mut c: Compiler) run_code_generator() bool {
   130→	c.log_debug("Starting Code Generator phase...")
   131→
   132→	if c.ast == none {
   133→		c.result.errors.push("AST not available")
   134→		return false
   135→	}
   136→
   137→	mut cg = new_code_generator()
   138→
   139→	// 헤더 생성
   140→	cg.generate_headers()
   141→
   142→	// 함수 선언 생성
   143→	cg.generate_function_declarations()
   144→
   145→	// 기본 main 함수 스텁
   146→	cg.generate_main_function("  return 0;\n")
   147→
   148→	if cg.has_errors() {
   149→		c.result.status = CompileStatus.CodeGenError
   150→		c.result.errors = cg.get_errors()
   151→		c.log_debug("Code Gen errors: ${c.result.errors.len()}")
   152→		return false
   153→	}
   154→
   155→	c.code_generator = cg
   156→	c.result.c_code = cg.get_output()
   157→
   158→	c.log_debug("Code Generator completed successfully")
   159→	c.log_debug("Generated C code length: ${c.result.c_code.len()} bytes")
   160→	return true
   161→}
   162→
   163→// ============= 메인 컴파일 함수 =============
   164→
   165→fn (mut c: Compiler) compile() CompileResult {
   166→	c.log_debug("=== Starting FV Compilation ===")
   167→	c.log_debug("Source code length: ${c.source_code.len()} bytes")
   168→
   169→	// Phase 1: Lexer
   170→	if !c.run_lexer() {
   171→		c.log_debug("Compilation failed at Lexer phase")
   172→		return c.result
   173→	}
   174→
   175→	// Phase 2: Parser
   176→	if !c.run_parser() {
   177→		c.log_debug("Compilation failed at Parser phase")
   178→		return c.result
   179→	}
   180→
   181→	// Phase 3: Type Checker
   182→	if !c.run_type_checker() {
   183→		c.log_debug("Compilation failed at Type Checker phase")
   184→		return c.result
   185→	}
   186→
   187→	// Phase 4: Code Generator
   188→	if !c.run_code_generator() {
   189→		c.log_debug("Compilation failed at Code Generator phase")
   190→		return c.result
   191→	}
   192→
   193→	c.result.status = CompileStatus.Success
   194→	c.log_debug("=== Compilation Successful ===")
   195→	return c.result
   196→}
   197→
